function waitUnit(){if(!selected||selected.acted)return;selected.acted=true;selected.moved=true;addLog(`${types[selected.type].name} holds position.`);renderUI()}
function checkResult(){if(living('enemy').length===0){gameOver=true;showResult(true)}else if(living('player').length===0){gameOver=true;showResult(false)}}
function showResult(win){document.getElementById('resultTitle').textContent=win?'VICTORY':'DEFEAT';document.getElementById('resultCopy').textContent=win?'The citadel is yours. Your company will be remembered.':'The arena has fallen. Regroup and fight again.';document.getElementById('overlay').classList.add('show');document.getElementById('tip').innerHTML=win?'<b>VICTORY</b> — the citadel is yours':'<b>DEFEAT</b> — regroup and try again';renderUI()}
function endPlayerTurn(){if(turn!=='player'||gameOver)return;selected=null;turn='enemy';document.getElementById('tip').innerHTML='<b>ENEMY PHASE</b> — the opposing force is moving';renderUI();setTimeout(enemyPhase,500)}
function enemyPhase(){if(gameOver)return;const foes=living('enemy').slice();let i=0;function step(){if(gameOver)return;if(i>=foes.length){turn='player';round++;for(const u of living('player')){u.moved=false;u.acted=false;u.guarding=false}selected=null;document.getElementById('tip').innerHTML='<b>YOUR TURN</b> — command your company';addLog(`Round ${round} begins. Your company regains its actions.`,'system');renderUI();return}
 const u=foes[i++];if(u.hp<=0){setTimeout(step,180);return}let targets=living('player');if(!targets.length){checkResult();return}
 let target=targets.slice().sort((a,b)=>dist(u,a)-dist(u,b))[0];if(dist(u,target)<=types[u.type].range){attack(u,target);setTimeout(step,520);return}
 let options=reachable(u);options.sort((a,b)=>{let da=Math.min(...targets.map(t=>Math.abs(a.x-t.x)+Math.abs(a.y-t.y))),db=Math.min(...targets.map(t=>Math.abs(b.x-t.x)+Math.abs(b.y-t.y)));return da-db});
 let best=options.find(pos=>targets.some(t=>Math.abs(pos.x-t.x)+Math.abs(pos.y-t.y)<=types[u.type].range))||options[0];if(best){u.x=best.x;u.y=best.y;let inRange=targets.filter(t=>dist(u,t)<=types[u.type].range).sort((a,b)=>a.hp-b.hp)[0];if(inRange){attack(u,inRange);setTimeout(step,560);return}addLog(`${types[u.type].name} closes in from the ruins.`,'enemy');renderUI();setTimeout(step,410);return}addLog(`${types[u.type].name} holds its ground.`,'enemy');setTimeout(step,300)}step()}
function restart(){setup()}
canvas.addEventListener('click',onBoardClick);canvas.addEventListener('pointermove',onPointerMove);canvas.addEventListener('pointerleave',()=>{hover=null;draw()});document.getElementById('endTurn').addEventListener('click',endPlayerTurn);document.getElementById('resetBtn').addEventListener('click',restart);document.getElementById('playAgain').addEventListener('click',restart);document.getElementById('guardBtn').addEventListener('click',setGuard);document.getElementById('waitBtn').addEventListener('click',waitUnit);window.addEventListener('resize',resize);window.addEventListener('keydown',e=>{if(e.key==='Escape'){selected=null;renderUI()}if(e.key==='Enter'&&turn==='player')endPlayerTurn()});
resize();setup();
})();
</script>
</body>
</html>

